#!/usr/bin/env python3
"""Convert the external dictionary sources in data/raw into the unified UTF-8 TSV
layout defined by agents/DECISIONS.md. Sources stay untouched; only derived TSVs
are written. Every generated file records its source, license and SHA256.

Single-character readings are merged from two sources:
  * CC-CEDICT (authoritative for common characters, tone digits)
  * data/old/pinyin_dict.txt (generated by pypinyin with heteronym=True, MIT)
Each merged row keeps a `sources` and `agreement` column so a later loader can
decide how much to trust polyphone readings. Characters that occur in the
dictionary or the character-frequency table but in neither reading source are
emitted explicitly as `unknown`, per DECISIONS.md section 4.

Usage:
  python tools/normalize_dicts.py            # write all TSVs + PROVENANCE.tsv
  python tools/normalize_dicts.py --check    # report row counts without writing
"""

from __future__ import annotations

import argparse
import datetime
import glob
import hashlib
import io
import json
import os
import re
import sys
import zipfile
import xml.etree.ElementTree as ET

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
RAW = os.path.join(ROOT, "data", "raw")
OLD = os.path.join(ROOT, "data", "old")
DATA = os.path.join(ROOT, "data")

SCRIPT = "tools/normalize_dicts.py"
U8 = "UTF-8"
SHEET_NS = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"

HAN_RANGES = ((0x3400, 0x4DBF), (0x4E00, 0x9FFF), (0xF900, 0xFAFF), (0x20000, 0x2FA1F))


def is_han(ch: str) -> bool:
    cp = ord(ch)
    return cp == 0x3007 or any(lo <= cp <= hi for lo, hi in HAN_RANGES)


def sha256(path: str) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(1 << 20), b""):
            digest.update(chunk)
    return digest.hexdigest()


def now() -> str:
    return datetime.datetime.now().isoformat(timespec="seconds")


def normalize_syllable(token: str) -> str:
    """CC-CEDICT tone digits -> the project convention: lowercase ASCII, v = ü."""
    text = token.strip().lower()
    text = text.replace("u:", "v").replace("Ü", "v").replace("ü", "v")
    text = text.replace("˙", "").replace("·", "")
    return re.sub(r"[^a-z1-9]", "", text)


def parse_pron_field(field: str) -> list[str]:
    """`[yi1bu4zuo4,er4bu4xiu1]` -> the list of alternative readings, normalized."""
    readings: list[str] = []
    for alternative in field.split(","):
        tokens = alternative.split()
        if not tokens:
            continue
        reading = "".join(normalize_syllable(token) for token in tokens)
        if reading and reading not in readings:
            readings.append(reading)
    return readings


def read_xlsx_rows(path: str) -> list[list[str]]:
    """Minimal xlsx reader: first worksheet, shared strings resolved."""
    archive = zipfile.ZipFile(path)
    shared: list[str] = []
    if "xl/sharedStrings.xml" in archive.namelist():
        node = ET.fromstring(archive.read("xl/sharedStrings.xml"))
        for item in node.findall(SHEET_NS + "si"):
            shared.append("".join(t.text or "" for t in item.iter(SHEET_NS + "t")))
    sheet_name = next(n for n in archive.namelist()
                      if re.match(r"xl/worksheets/sheet1?\.xml$", n))
    node = ET.fromstring(archive.read(sheet_name))
    rows: list[list[str]] = []
    for row in node.find(SHEET_NS + "sheetData").findall(SHEET_NS + "row"):
        cells: list[str] = []
        for cell in row.findall(SHEET_NS + "c"):
            value = cell.find(SHEET_NS + "v")
            if value is None:
                inline = cell.find(SHEET_NS + "is")
                cells.append("".join(t.text or "" for t in inline.iter(SHEET_NS + "t"))
                             if inline is not None else "")
            elif cell.get("t") == "s":
                cells.append(shared[int(value.text)])
            else:
                cells.append(value.text or "")
        rows.append(cells)
    return rows


def write_tsv(path: str, header: list[str], rows: list[list[str]], meta: dict) -> None:
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with io.open(path, "w", encoding=U8, newline="\n") as out:
        for key in ("role", "source", "source_license", "columns", "note", "generated_by", "generated_at"):
            if key in meta:
                out.write("# %s: %s\n" % (key, meta[key]))
        out.write("\t".join(header) + "\n")
        for row in rows:
            out.write("\t".join(row) + "\n")


def load_ac_lock() -> tuple[list[list[str]], dict]:
    src = os.path.join(RAW, "AC_word.txt")
    rows, group, seen = [], "", set()
    for line in io.open(src, encoding=U8):
        line = line.strip()
        if not line:
            continue
        if line.startswith("#"):
            group = line.lstrip("#").strip()
            continue
        if line in seen:
            continue
        seen.add(line)
        rows.append([line, group])
    return rows, dict(role="AC 锁定词表（只有 LOCK 一种动作）",
                      source="data/raw/AC_word.txt（人工维护）",
                      source_license="人工整理，无外部许可",
                      columns="word\tgroup",
                      note="源里的 ##分组标记 保留为 group 列；重复词只留一条",
                      generated_by=SCRIPT, generated_at=now())


def load_rime(filename: str, role: str) -> tuple[list[list[str]], dict]:
    src = os.path.join(RAW, "rime", filename)
    started, best, duplicates = False, {}, 0
    for line in io.open(src, encoding=U8):
        if not started:
            started = line.strip() == "..."
            continue
        line = line.rstrip("\n")
        if not line or line.startswith("#"):
            continue
        fields = line.split("\t")
        word = fields[0].strip()
        if not word:
            continue
        weight = fields[2].strip() if len(fields) > 2 else ""
        if word in best:
            duplicates += 1
            if weight.isdigit() and (not best[word].isdigit() or int(weight) > int(best[word])):
                best[word] = weight
            continue
        best[word] = weight
    rows = [[word, best[word]] for word in sorted(best)]
    meta = dict(role=role,
                source="data/raw/rime/%s（iDvel/rime-ice）" % filename,
                source_license="上游未在该文件声明许可，见 https://github.com/iDvel/rime-ice（待确认）",
                columns="word\tweight",
                note="读音一律由 pronunciation*.tsv 提供，这里不重复存放 rime 的无声调拼音；同名取最大 weight，合并 %d 条" % duplicates,
                generated_by=SCRIPT, generated_at=now())
    return rows, meta


def load_cedict() -> tuple[dict, list[list[str]], list[list[str]], dict]:
    src = os.path.join(RAW, "cedict_ts.u8")
    readings: dict[str, list[str]] = {}
    for line in io.open(src, encoding=U8):
        if line.startswith("#"):
            continue
        match = re.match(r"^(\S+) (\S+) \[([^\]]+)\]", line)
        if not match:
            continue
        simplified = match.group(2)
        for reading in parse_pron_field(match.group(3)):
            bucket = readings.setdefault(simplified, [])
            if reading not in bucket:
                bucket.append(reading)
    word_rows = [[w, "|".join(v)] for w, v in sorted(readings.items()) if len(w) >= 2]
    char_rows = [[w, "|".join(v)] for w, v in sorted(readings.items()) if len(w) == 1]
    meta = dict(role="词级读音（声调数字后缀，v 表示 ü）；| 分隔＝同一词的多个读音",
                source="data/raw/cedict_ts.u8（CC-CEDICT，MDBG 发布）",
                source_license="CC BY-SA 4.0",
                columns="entry\treadings",
                note="方括号内逗号分隔的多读音拆成 | 分隔，不再拼成一串；只保留简体侧",
                generated_by=SCRIPT, generated_at=now())
    return readings, word_rows, char_rows, meta


def load_pypinyin_chars() -> tuple[dict, str]:
    """data/old/pinyin_dict.txt: <hex codepoint>TAB<syllable>[,<syllable>...]."""
    src = os.path.join(OLD, "pinyin_dict.txt")
    version = "unknown"
    mapping: dict[str, list[str]] = {}
    for line in io.open(src, encoding=U8):
        if line.startswith("#"):
            found = re.search(r"pypinyin\s+([\d.]+)", line)
            if found:
                version = found.group(1)
            continue
        if not line.strip():
            continue
        parts = line.rstrip("\n").split("\t", 1)
        if len(parts) < 2:
            continue
        try:
            ch = chr(int(parts[0], 16))
        except ValueError:
            continue
        readings = []
        for raw in parts[1].split(","):
            reading = normalize_syllable(raw)
            if reading and reading not in readings:
                readings.append(reading)
        if readings:
            mapping[ch] = readings
    return mapping, version


def build_char_pronunciation(cedict: dict, pinyin_map: dict, pinyin_version: str,
                             needed_chars: set) -> tuple[list[list[str]], dict, dict]:
    """Single-char readings with CEDICT as the authority (园长大决定 2026-11-06):

    * 有 CEDICT 记录的字 -> 只保留 CEDICT 的读音，pypinyin 多出的异读全部丢弃
    * 仅 pypinyin 覆盖的字 -> 只保留 pypinyin 的第一个（常用）读音，其余异读丢弃
    * 两源皆无 -> 记 unknown
    丢弃的读音写进 dropped 列，保证这条策略是可审计、可回退的（原始两源都在盘上）。
    """
    chars = set(cedict) | set(pinyin_map) | set(needed_chars)
    rows, stats = [], {}
    for ch in sorted(chars):
        c_read = list(cedict.get(ch, []))
        p_read = list(pinyin_map.get(ch, []))
        if not c_read and not p_read:
            rows.append([ch, "unknown", "none", "missing", ""])
            stats["missing"] = stats.get("missing", 0) + 1
            continue
        if c_read:
            kept, sources = c_read, "cedict"
            dropped = [r for r in p_read if r not in c_read]
        else:
            kept, sources = p_read[:1], "pypinyin_primary"
            dropped = p_read[1:]
        cset, pset = set(c_read), set(p_read)
        if cset and pset:
            agreement = "agree" if cset == pset else ("cedict_subset" if cset <= pset else "conflict")
        elif pset:
            agreement = "pypinyin_only"
        else:
            agreement = "cedict_only"
        stats[agreement] = stats.get(agreement, 0) + 1
        stats["_dropped"] = stats.get("_dropped", 0) + len(dropped)
        rows.append([ch, "|".join(kept), sources, agreement, "|".join(dropped)])
    meta = dict(role="单字读音（声调数字后缀，v 表示 ü）；| 分隔＝该字保留的多个读音，首项为常用音",
                source="data/raw/cedict_ts.u8（CC-CEDICT，权威）+ data/old/pinyin_dict.txt（pypinyin %s，仅作补充）" % pinyin_version,
                source_license="CC BY-SA 4.0 + MIT",
                columns="char\treadings\tsources\tagreement\tdropped",
                note=("策略（园长大决定 2026-11-06）：以 CEDICT 为准，罕见异读删除。"
                      "有 CEDICT 记录的字只留 CEDICT 读音；仅 pypinyin 覆盖的字只留其首个常用读音；"
                      "两源皆无标 unknown。agreement 保留合并时的源间关系（agree/cedict_subset/conflict/"
                      "pypinyin_only/cedict_only/missing），dropped 列记录被删掉的异读，便于审计与回退。"
                      "被删读音的例子：有 you4/wei3、信 shen1 —— 文言异读正是旧缺陷 D3 的误改通道。"),
                generated_by=SCRIPT, generated_at=now())
    return rows, meta, stats


def load_subtlex(filename: str, kind: str) -> dict[str, tuple[str, str]]:
    """SUBTLEX-CH xlsx -> {entry: (count, context_count)}. Kept as a fallback source."""
    src = os.path.join(RAW, filename)
    out: dict[str, tuple[str, str]] = {}
    for cells in read_xlsx_rows(src):
        if not cells:
            continue
        head = cells[0].strip()
        if not head or head.startswith("Total") or head in ("Word", "Character", "Context number: 6,243"):
            continue
        if kind == "word" and len(head) < 2:
            continue
        if kind == "char" and len(head) != 1:
            continue
        if len(cells) < 5:
            continue
        out[head] = (str(int(float(cells[1]))), cells[4])
    return out


def load_wordfreq():
    try:
        import wordfreq
        from wordfreq import zipf_frequency
    except ImportError:
        return None, "missing"
    try:
        from importlib import metadata
        version = metadata.version("wordfreq")
    except Exception:
        version = getattr(wordfreq, "__version__", "unknown")
    return zipf_frequency, version


DOMAIN_PATTERNS = ("asr/*.gt.txt", "temp_txt/*.txt")
DOMAIN_EXCLUDE = ("九曲安澜万象新",)          # 0 字节占位文件


def load_domain_corpus() -> tuple[dict, dict, int, list, bool, str]:
    """Count characters and words in our own subtitle/ASR ground-truth corpus."""
    files = []
    for pattern in DOMAIN_PATTERNS:
        for path in sorted(glob.glob(os.path.join(ROOT, pattern))):
            if any(bad in path for bad in DOMAIN_EXCLUDE):
                continue
            text = io.open(path, encoding=U8, errors="replace").read()
            if len(text.strip()) == 0:
                continue
            files.append((path, text))
    total_chars = sum(len(text) for _, text in files)
    chars: dict[str, int] = {}
    for _, text in files:
        for ch in text:
            if is_han(ch):
                chars[ch] = chars.get(ch, 0) + 1
    words: dict[str, int] = {}
    segmented = False
    try:
        import jieba
        segmented = True
        for _, text in files:
            for token in jieba.lcut(text):
                if len(token) >= 2 and all(is_han(ch) for ch in token):
                    words[token] = words.get(token, 0) + 1
    except ImportError:
        pass
    names = ",".join(os.path.basename(p) for p, _ in files)
    return chars, words, total_chars, files, segmented, names


def build_word_freq(zipf, entries: set, ours: dict, fallback: dict,
                    corpus_chars: int, corpus_tag: str) -> tuple[list[list[str]], dict, str]:
    """word 列：通用 zipf + 本项目领域计数（可随语料增长重算）。"""
    rows, mode = [], "wordfreq" if zipf else "subtlex_fallback"
    for word in sorted(entries):
        general = round(float(zipf(word, "zh")), 3) if zipf else ""
        sub_count = "" if zipf else fallback.get(word, ("", ""))[0]
        ours_count = ours.get(word, 0)
        per_mil = round(ours_count * 1e6 / corpus_chars, 1) if corpus_chars and ours_count else ""
        if zipf:
            hit = general > 0
        else:
            hit = bool(sub_count)
        sources = "+".join([s for s, ok in (("wordfreq", hit), ("subtlex", bool(sub_count)),
                                            ("ours", ours_count > 0)) if ok]) or "none"
        value = general if zipf else sub_count
        rows.append([word, str(value), str(ours_count), str(per_mil), sources])
    meta = dict(role="词频：通用底库 + 本项目字幕/真值领域计数（领域列可动态重算）",
                source=("wordfreq %s（多源合并：维基百科/字幕/社交/图书）" % corpus_tag if zipf
                        else "SUBTLEX-CH-WF（wordfreq 不可用时的回退，未换库）"),
                source_license="wordfreq 数据 CC BY-SA 4.0（代码 Apache-2.0）；SUBTLEX 仅限学术用途",
                columns="word\tgeneral\tours_count\tours_per_million\tsources",
                note=("general 列：wordfreq 给的是 zipf 指数（log10 尺度，越大越常见），不是次数；"
                      "换算 ln(fC/fO) = 2.3026 x (zipfC - zipfO)。"
                      "领域列来自 %s（本次共 %d 字，分词用 jieba），语料增长后重跑本脚本即可刷新。"
                      "sources 标明该行证据来自哪些库；none 表示两边都没查到。"
                      % (corpus_tag, corpus_chars)),
                generated_by=SCRIPT, generated_at=now())
    return rows, meta, mode


def build_char_freq(zipf, chars: set, ours: dict, fallback: dict,
                    corpus_chars: int) -> tuple[list[list[str]], dict]:
    rows = []
    for ch in sorted(chars):
        general = round(float(zipf(ch, "zh")), 3) if zipf else ""
        sub_count = "" if zipf else fallback.get(ch, ("", ""))[0]
        ours_count = ours.get(ch, 0)
        per_mil = round(ours_count * 1e6 / corpus_chars, 1) if corpus_chars and ours_count else ""
        if zipf:
            hit = general > 0
        else:
            hit = bool(sub_count)
        sources = "+".join([s for s, ok in (("wordfreq", hit), ("subtlex", bool(sub_count)),
                                            ("ours", ours_count > 0)) if ok]) or "none"
        value = general if zipf else sub_count
        rows.append([ch, str(value), str(ours_count), str(per_mil), sources])
    meta = dict(role="字频：通用底库 + 本项目语料字计数（领域列可动态重算）",
                source="wordfreq（单字 zipf）" if zipf else "SUBTLEX-CH-CHR（回退）",
                source_license="wordfreq 数据 CC BY-SA 4.0；SUBTLEX 仅限学术用途",
                columns="char\tgeneral\tours_count\tours_per_million\tsources",
                note="general 为 zipf 指数；领域列来自本项目 asr 真值 + temp_txt，共 %d 字。" % corpus_chars,
                generated_by=SCRIPT, generated_at=now())
    return rows, meta


HUMAN_PATTERNS = ("asr/*.decisions.user.json", "asr/*.decisions.round*.json")
AGENT_PATTERNS = ("asr/*.decisions.agent.json", "asr/*.decisions.merged.json",
                  "asr/*.decisions.audited.json")
CC_PATTERNS = ("asr/*.decisions.cc.json",)
OVERRIDE_PATTERNS = ("asr/*.overrides.json",)
GT_JSONL_PATTERNS = ("asr/*.gt.jsonl",)

PRIORITY = {"LLM 提议": 1, "真实语料挖掘": 2, "人工确认": 3}
MAX_CANONICAL_LEN = 6      # 候选目标词最长 6 字；整句级修正不入候选词库


def _iter_json(paths):
    for pattern in paths:
        for path in sorted(glob.glob(os.path.join(ROOT, pattern))):
            try:
                yield path, json.load(io.open(path, encoding=U8))
            except (ValueError, OSError):
                continue


def _decision_pairs(payload: dict) -> list[tuple[str, str]]:
    """decisions 键格式 `<kind>:<cue>:<错词>:<对词>`；d=A 采纳替换，d=C 用户自填。"""
    out = []
    for key, value in (payload.get("decisions") or {}).items():
        parts = key.split(":", 3)
        if len(parts) < 4:
            continue
        frm, to = parts[2].strip(), parts[3].strip()
        choice = value.get("d")
        if choice == "A" and to:
            out.append((to, frm))
        elif choice == "C":
            filled = (value.get("text") or "").strip()
            if filled:
                out.append((filled, frm))
    return out


def collect_gt_candidates() -> tuple[dict, dict]:
    """从人工真值与各轮决策文件里抽 (对词, 错词) 配对，并标注来源。"""
    pairs: dict[tuple[str, str], str] = {}
    stats: dict[str, int] = {}

    def offer(canonical: str, alias: str, source: str) -> None:
        if not canonical or not alias or canonical == alias:
            return
        if not all(is_han(ch) for ch in canonical + alias):
            stats["跳过_含非汉字"] = stats.get("跳过_含非汉字", 0) + 1
            return
        if len(canonical) != len(alias):
            # 拼音对齐距离要求词长相同，漏字/多字型修正走不了这条通道
            stats["跳过_长度不等"] = stats.get("跳过_长度不等", 0) + 1
            return
        if len(canonical) > MAX_CANONICAL_LEN:
            stats["跳过_整句级"] = stats.get("跳过_整句级", 0) + 1
            return
        key = (canonical, alias)
        if pairs.get(key) and PRIORITY[pairs[key]] >= PRIORITY[source]:
            return
        if key in pairs:
            stats["升级来源"] = stats.get("升级来源", 0) + 1
        pairs[key] = source

    for path, payload in _iter_json(GT_JSONL_PATTERNS):
        for line in io.open(path, encoding=U8):
            if not line.strip():
                continue
            record = json.loads(line)
            for hit in record.get("applied") or []:
                offer(str(hit.get("a", "")).strip(), str(hit.get("w", "")).strip(), "真实语料挖掘")

    for path, payload in _iter_json(OVERRIDE_PATTERNS):
        for item in payload if isinstance(payload, list) else []:
            frm_list = item.get("frm")
            frm_list = frm_list if isinstance(frm_list, list) else [frm_list]
            for frm in frm_list:
                offer(str(item.get("to", "")).strip(), str(frm).strip(), "人工确认")

    for group, source in ((HUMAN_PATTERNS, "人工确认"),
                          (AGENT_PATTERNS, "LLM 提议"),
                          (CC_PATTERNS, "真实语料挖掘")):
        for path, payload in _iter_json(group):
            for canonical, alias in _decision_pairs(payload):
                offer(canonical, alias, source)

    stats["配对总数"] = len(pairs)
    return pairs, stats


def load_candidates(readings: dict, char_readings: dict) -> tuple[list[list[str]], dict, list[str]]:
    entries: dict[tuple[str, str], tuple[str, str]] = {}

    def pinyin_of(canonical: str) -> str:
        if canonical in readings:
            return readings[canonical][0]
        if canonical and all(ch in char_readings for ch in canonical):
            return "".join(char_readings[ch][0] for ch in canonical)
        return "unknown"

    src = os.path.join(OLD, "lexicon.txt")
    notes: list[str] = []
    for line in io.open(src, encoding=U8):
        line = line.rstrip("\n")
        if not line or line.startswith("#"):
            continue
        fields = line.split("\t")
        canonical = fields[0].strip()
        action = fields[3].strip().lower() if len(fields) > 3 else "replace"
        status = "1" if action == "replace" else "0"
        if action != "replace":
            notes.append("%s：旧动作 %s 在新架构无对应位置（AC 只有 LOCK），状态置 0 停用" % (canonical, action))
        aliases: list[str] = []
        if len(fields) > 2 and fields[2].strip():
            aliases = [a.strip() for a in re.split(r"[,，]", fields[2]) if a.strip()]
        for alias in aliases or [""]:
            entries[(canonical, alias)] = ("人工确认", status)

    gt_pairs, gt_stats = collect_gt_candidates()
    single_char = 0
    for (canonical, alias), source in gt_pairs.items():
        status = "1" if source == "人工确认" else "0"
        if len(canonical) < 2:
            # 现架构窗口最短 2 字，单字目标词永远命中不了；先入库标停用，
            # 等源码开了单字替换通道再启用。
            status, single_char = "0", single_char + 1
        key = (canonical, alias)
        if key in entries:
            previous = entries[key][0]
            if PRIORITY[source] > PRIORITY[previous]:
                entries[key] = (source, status)
            continue
        entries[key] = (source, status)

    rows = [[canonical, pinyin_of(canonical), alias, source, status]
            for (canonical, alias), (source, status) in sorted(entries.items())]
    rows.sort(key=lambda r: (r[0], r[2]))
    notes.append("单字目标词 %d 条按停用入库（窗口最短 2 字，现架构用不上）" % single_char)
    meta = dict(role="候选词库（目标词 + 别称，一个别称一行）",
                source="data/old/lexicon.txt（人工维护）+ asr/ 人工真值与各轮 decisions；读音取自 CEDICT，缺失时用单字表首读音拼",
                source_license="项目自产；读音继承 CC-CEDICT CC BY-SA 4.0 与 pypinyin MIT",
                columns="canonical\tpinyin\talias\tsource\tstatus",
                note=("来源可信度：人工确认 > 真实语料挖掘 > LLM 提议（园长大决定：人工判定的与 LLM 确认的都补进来）。"
                      "status 1 启用 0 停用——只有人工确认且目标词长度≥2 才自动启用；"
                      "LLM 提议与真实语料挖掘一律先停用，等你点头再批量启用。"
                      "收录范围：两侧均为汉字、长度相等、目标词不超过 %d 字（拼音对齐要求等长，"
                      "漏字/多字型修正与整句级自填走不了这条通道，已按统计剔除）。"
                      "本次抽取统计：%s。mask 类条目暂无去处，保持停用。"
                      % (MAX_CANONICAL_LEN,
                         "，".join("%s %s" % (k, v) for k, v in sorted(gt_stats.items())))),
                generated_by=SCRIPT, generated_at=now())
    return rows, meta, notes


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true", help="只报告，不写文件")
    args = parser.parse_args()

    jobs: list[tuple[str, list[str], list[list[str]], dict]] = []

    ac, ac_meta = load_ac_lock()
    jobs.append(("data/ac/ac_lock.tsv", ["word", "group"], ac, ac_meta))

    base, base_meta = load_rime("base.dict.yaml", "普通词汇参考（基础词典）")
    jobs.append(("data/vocabulary/vocabulary.tsv", ["word", "weight"], base, base_meta))
    ext, ext_meta = load_rime("ext.dict.yaml", "普通词汇参考（拓展词典）")
    jobs.append(("data/vocabulary/extvocabulary.tsv", ["word", "weight"], ext, ext_meta))

    readings, word_rows, char_rows, pron_meta = load_cedict()
    jobs.append(("data/pronunciation/pronunciation.tsv", ["entry", "readings"], word_rows, pron_meta))

    cedict_chars = {row[0]: row[1].split("|") for row in char_rows}
    pinyin_map, pinyin_version = load_pypinyin_chars()
    needed = set()
    for rows, _ in ((ac, ac_meta), (base, base_meta), (ext, ext_meta)):
        for row in rows:
            needed.update(ch for ch in row[0] if is_han(ch))
    subtlex_chr = load_subtlex("SUBTLEX-CH-CHR.xlsx", "char")
    subtlex_wf = load_subtlex("SUBTLEX-CH-WF.xlsx", "word")
    needed.update(ch for ch in subtlex_chr if is_han(ch))
    char_rows_merged, char_meta, stats = build_char_pronunciation(
        cedict_chars, pinyin_map, pinyin_version, needed)
    jobs.append(("data/pronunciation/pronunciation_char.tsv",
                 ["char", "readings", "sources", "agreement", "dropped"], char_rows_merged, char_meta))

    zipf, wf_version = load_wordfreq()
    domain_chars, domain_words, domain_total, _files, segmented, domain_tag = load_domain_corpus()
    word_entries = ({row[0] for row in base} | {row[0] for row in ext}
                    | set(subtlex_wf) | {w for w in domain_words if len(w) >= 2})
    word_entries = {w for w in word_entries if len(w) >= 2}
    wf_rows, wf_meta, freq_mode = build_word_freq(
        zipf, word_entries, domain_words, subtlex_wf, domain_total, wf_version)
    jobs.append(("data/frequency/word_freq.tsv",
                 ["word", "general", "ours_count", "ours_per_million", "sources"], wf_rows, wf_meta))
    char_entries = set(subtlex_chr) | set(domain_chars) | {ch for w in word_entries for ch in w if is_han(ch)}
    cf_rows, cf_meta = build_char_freq(zipf, char_entries, domain_chars, subtlex_chr, domain_total)
    jobs.append(("data/frequency/char_freq.tsv",
                 ["char", "general", "ours_count", "ours_per_million", "sources"], cf_rows, cf_meta))
    print("词频底库：%s（版本 %s）；领域语料 %d 字，分词 %s"
          % ("wordfreq" if zipf else "SUBTLEX 回退", wf_version, domain_total,
             "jieba" if segmented else "不可用（仅字计数）"))
    for probe in ("微信", "支付宝", "字节跳动", "抖音", "腾讯", "华为", "银行卡", "转账", "验证码", "敏感词"):
        line = next((r for r in wf_rows if r[0] == probe), None)
        print("   热词 %-5s general=%-7s 我方语料次数=%-4s 来源=%s"
              % (probe, line[1] if line else "-", line[2] if line else "-", line[4] if line else "-"))

    char_first = {row[0]: row[1].split("|") for row in char_rows_merged if row[1] != "unknown"}
    cand, cand_meta, notes = load_candidates(readings, char_first)
    jobs.append(("data/correction/candidates.tsv",
                 ["canonical", "pinyin", "alias", "source", "status"], cand, cand_meta))
    dist: dict[str, int] = {}
    for row in cand:
        dist["%s/%s" % (row[3], "启用" if row[4] == "1" else "停用")] = dist.get("%s/%s" % (row[3], "启用" if row[4] == "1" else "停用"), 0) + 1
    print("候选词库 %d 行，目标词 %d 个，来源分布 %s"
          % (len(cand), len({row[0] for row in cand}), dist))

    for rel, header, rows, meta in jobs:
        if not args.check:
            write_tsv(os.path.join(ROOT, *rel.split("/")), header, rows, meta)
        print("%-46s %8d 行" % (rel, len(rows)))

    # 覆盖率自检：单字表补齐后，词库条目能拼出读音的比例
    vocab = {row[0] for row in base} | {row[0] for row in ext}
    have_word = set(readings)
    compos = sum(1 for w in vocab if all(ch in char_first for ch in w))
    uncovered = sorted({ch for w in vocab for ch in w if is_han(ch) and ch not in char_first})
    freq_cov = sum(1 for row in cf_rows if row[0] in char_first)
    print("\n单字表合并结果: pypinyin %s，共 %d 字；一致性 %s" % (pinyin_version, len(char_rows_merged), stats))
    print("词典 %d 条：有词级读音 %d，可用单字拼出 %d，两者都不行 %d"
          % (len(vocab), len(vocab & have_word), compos,
             sum(1 for w in vocab if w not in have_word and not all(ch in char_first for ch in w))))
    print("字频表 %d 字：读音覆盖 %d；仍缺读音的汉字 %d 个 %s"
          % (len(cf_rows), freq_cov, len(uncovered),
             [ch.encode("unicode_escape").decode() for ch in uncovered[:10]]))

    if not args.check:
        os.makedirs(os.path.join(DATA, "generated"), exist_ok=True)
        with io.open(os.path.join(DATA, "generated", "README.md"), "w", encoding=U8, newline="\n") as out:
            out.write("# generated/\n\n"
                      "本目录内容（如 `pinyin_index.bin`）由程序从 `correction/candidates.tsv`\n"
                      "和 `pronunciation/*.tsv` 自动重建，**不允许人工编辑**。\n\n"
                      "当前状态：生产代码尚未实现 BIN 读写，目录为空属预期。\n")
        prov_path = os.path.join(DATA, "PROVENANCE.tsv")
        stamp = now()
        with io.open(prov_path, "w", encoding=U8, newline="\n") as out:
            out.write("# 统一数据格式要求：每份外部数据记录来源、版本、许可和 SHA256\n")
            out.write("path\trole\tsource\tlicense\tsha256\tsize_bytes\tupdated_at\n")
            raw_rows = [
                ("data/raw/AC_word.txt", "AC 锁定词源", "人工维护", "无外部许可"),
                ("data/raw/target_lexion.txt", "候选词库格式样例（仅注释，无数据）", "人工维护", "无外部许可"),
                ("data/raw/cedict_ts.u8", "词/字读音源", "CC-CEDICT (MDBG)", "CC BY-SA 4.0"),
                ("data/raw/SUBTLEX-CH-WF.xlsx", "词频对照/回退源（通用底库已换 wordfreq）", "SUBTLEX-CH", "仅限学术用途"),
                ("data/raw/SUBTLEX-CH-CHR.xlsx", "字频对照/回退源（通用底库已换 wordfreq）", "SUBTLEX-CH", "仅限学术用途"),
                ("data/raw/rime/base.dict.yaml", "基础词典源", "iDvel/rime-ice", "上游未声明，待确认"),
                ("data/raw/rime/ext.dict.yaml", "拓展词典源", "iDvel/rime-ice", "上游未声明，待确认"),
                ("data/old/lexicon.txt", "旧动作词表（candidates 数据来源）", "本项目人工维护", "项目自产"),
                ("data/old/pinyin_dict.txt", "单字读音源（pypinyin %s，heteronym）" % pinyin_version,
                 "mozillazg/python-pinyin", "MIT"),
                ("data/old/word_freq.txt", "旧词频表（由 jieba dict.txt 派生）", "jieba dict.txt", "MIT"),
                ("data/old/dict.txt", "旧通用词典（jieba）", "fxsjy/jieba", "MIT"),
                ("data/old/SUBTLEX-CH-WF", "词频源文本版（GB18030 编码）", "SUBTLEX-CH", "仅限学术用途"),
                ("data/old/THUOCL_chengyu.txt", "成语词表（实验用，未进生产）", "THUOCL (thuopen)", "待确认"),
                ("data/old/THUOCL_diming.txt", "地名词表（实验用，未进生产）", "THUOCL (thuopen)", "待确认"),
                ("data/old/word.txt.seed.bak", "旧 AC 词表备份", "本项目人工维护", "项目自产"),
                ("data/old/sample_document.txt", "用途不明（全仓零引用）", "未知", "待确认"),
            ]
            for rel, role, source, license_ in raw_rows:
                path = os.path.join(ROOT, *rel.split("/"))
                if not os.path.exists(path):
                    out.write("%s\t%s\t%s\t%s\tMISSING\t0\t%s\n" % (rel, role, source, license_, stamp))
                    continue
                out.write("%s\t%s\t%s\t%s\t%s\t%d\t%s\n" % (
                    rel, role, source, license_, sha256(path), os.path.getsize(path), stamp))
            out.write("# --- 外部程序库（非文件，SHA256 由 pip 元数据管理）---\n")
            out.write("wordfreq\t通用词频/字频底库（zipf 指数）\trspeer/wordfreq，多源合并\t代码 Apache-2.0，数据 CC BY-SA 4.0\tversion=%s\t0\t%s\n"
                      % (wf_version, stamp))
            out.write("jieba\t领域语料分词（只用于统计我方语料）\tfxsjy/jieba\tMIT\t见 pip 元数据\t0\t%s\n" % stamp)
            out.write("asr/*.gt.txt + temp_txt/*.txt\t领域语料（本项目人工真值与参考正文）\t本项目\t真值不得外发\t%d 字\t0\t%s\n"
                      % (domain_total, stamp))
            out.write("# --- 生成的正式词库 ---\n")
            for rel, _, rows, _ in jobs:
                path = os.path.join(ROOT, *rel.split("/"))
                out.write("%s\t生成物 %d 行\t由 %s 从 data/raw+data/old 转换\t派生许可见来源\t%s\t%d\t%s\n" % (
                    rel, len(rows), SCRIPT, sha256(path), os.path.getsize(path), stamp))
        with io.open(prov_path, encoding=U8) as check:
            prov_lines = sum(1 for line in check if line.strip() and not line.startswith("#")) - 1
        print("%-46s %8d 行" % ("data/PROVENANCE.tsv", prov_lines))

    for note in notes:
        print("提示: " + note)
    if args.check:
        print("(--check: 未写入任何文件)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
